package services.INO;

import data.ClaimRecord;
import data.Claims;
import data.EncryptedVerifiedClaim;
import data.VerifiedClaim;
import util.DHUtil;

import java.util.List;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

// This is used to store the session key generated by the key agreement . This allows same client to come in again and execute a new key agreement.


public class VerifiedClaimCache {


    DynamoDBPersistenceManagerForClaims manager = new DynamoDBPersistenceManagerForClaims();

    Map<String, EncryptedVerifiedClaim> cache = new ConcurrentHashMap<>();

    public void put(String transactionId , EncryptedVerifiedClaim claim)
    {

        manager.createClaim(transactionId,claim);
    }

    public EncryptedVerifiedClaim get(String transactionId)
    {

        return manager.getClaim(transactionId);
    }


    public Claims getAllClaims()
    {
        return manager.getAllClaims();
    }

    public List<ClaimRecord> getAllClaimIds()
    {
        return manager.getAllClaimIds();
    }

    public void deleteClaim(String claimId)
    {
        manager.deleteClaim(claimId);
    }


    public void deleteClaims()
    {
        manager.deleteClaims();
    }

    @Override
    public String toString() {
        return "SessionKeyCache{" +
                "cache=" + cache +
                '}';
    }
}
